--
-- Name: generate_random_quote_serial(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_random_quote_serial() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  chars  TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; -- بدون أحرف/أرقام ملتبسة (0/O, 1/I)
  result TEXT := '';
  i INT;
BEGIN
  FOR i IN 1..4 LOOP
    result := result || substr(chars, (floor(random()*length(chars))+1)::int, 1);
  END LOOP;
  result := result || '-';
  FOR i IN 1..4 LOOP
    result := result || substr(chars, (floor(random()*length(chars))+1)::int, 1);
  END LOOP;
  RETURN result;
END;
$$;


