--
-- Name: recompute_catalog_stock(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recompute_catalog_stock(p_catalog_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_qty  NUMERIC(12,3);
  v_date DATE;
  v_last NUMERIC(12,3);
BEGIN
  SELECT COALESCE(SUM(quantity),0) INTO v_qty
  FROM public.stock_movements WHERE catalog_id = p_catalog_id;

  SELECT movement_date, quantity INTO v_date, v_last
  FROM public.stock_movements
  WHERE catalog_id = p_catalog_id
  ORDER BY movement_date DESC NULLS LAST, created_at DESC
  LIMIT 1;

  UPDATE public.catalog_items
  SET qty_on_hand = v_qty, last_received_at = v_date, last_received_qty = v_last
  WHERE id = p_catalog_id;
END;
$$;


ALTER FUNCTION public.recompute_catalog_stock(p_catalog_id uuid) OWNER TO postgres;

