--
-- Name: trg_stock_movements_sync(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_stock_movements_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.recompute_catalog_stock(OLD.catalog_id);
    RETURN OLD;
  ELSE
    PERFORM public.recompute_catalog_stock(NEW.catalog_id);
    IF TG_OP = 'UPDATE' AND OLD.catalog_id IS DISTINCT FROM NEW.catalog_id THEN
      PERFORM public.recompute_catalog_stock(OLD.catalog_id);
    END IF;
    RETURN NEW;
  END IF;
END;
$$;


ALTER FUNCTION public.trg_stock_movements_sync() OWNER TO postgres;

