CREATE VIEW public.order_summary AS
 SELECT o.id,
    o.number,
    o.quotation_number,
    o.customer_name,
    o.total_amount,
    o.currency,
    o.status,
    p.full_name AS created_by_name,
    o.created_at,
    o.archived
   FROM (public.orders o
     LEFT JOIN public.profiles p ON ((p.id = o.created_by)));


