--
-- Name: supply_files supply_files_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY supply_files_select ON public.supply_files FOR SELECT TO authenticated USING (((auth.uid() IS NOT NULL) AND ((public.get_my_role() = ANY (ARRAY['admin'::text, 'manager'::text])) OR ((public.get_my_role() = 'employee'::text) AND public.has_perm('supply_chain_access'::text)))));


--
-- Name: supply_files supply_files_update; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY supply_files_update ON public.supply_files FOR UPDATE TO authenticated USING (((created_by = auth.uid()) OR (public.get_my_role() = ANY (ARRAY['admin'::text, 'manager'::text])) OR ((public.get_my_role() = 'employee'::text) AND public.has_perm('supply_chain_edit'::text))));


--
-- Name: supply_file_stages supply_stages_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY supply_stages_select ON public.supply_file_stages FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.supply_files f
  WHERE ((f.id = supply_file_stages.file_id) AND ((public.get_my_role() = ANY (ARRAY['admin'::text, 'manager'::text])) OR ((public.get_my_role() = 'employee'::text) AND public.has_perm('supply_chain_access'::text)))))));


--
-- Name: supply_file_stages supply_stages_write; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY supply_stages_write ON public.supply_file_stages TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.supply_files f
  WHERE ((f.id = supply_file_stages.file_id) AND ((f.created_by = auth.uid()) OR (public.get_my_role() = ANY (ARRAY['admin'::text, 'manager'::text])) OR ((public.get_my_role() = 'employee'::text) AND (public.has_perm('supply_chain_edit'::text) OR public.has_perm('supply_chain_create'::text)))))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.supply_files f
  WHERE ((f.id = supply_file_stages.file_id) AND ((f.created_by = auth.uid()) OR (public.get_my_role() = ANY (ARRAY['admin'::text, 'manager'::text])) OR ((public.get_my_role() = 'employee'::text) AND (public.has_perm('supply_chain_edit'::text) OR public.has_perm('supply_chain_create'::text))))))));


